from lv_surrogate.physics.cardiac_residual import CardiacFirstStep
from lv_surrogate.physics.fem_bridge import FEMBridge
P=Path(__file__).resolve().parents[1];torch.set_num_threads(4);a=np.load(P/'data/processed/cardiac/cohort.npz');own=CardiacFirstStep(a);bridge=FEMBridge(P);idx=15;pressure=float(a['pressures'][idx]);u=a['displacements'][idx];reference=bridge.evaluate(u,pressure);res=own(torch.tensor(u),pressure).detach().numpy();absolute=float(np.max(np.abs(res-reference['residual'])));scale=float(a['force_scale_N']);norm=float(np.linalg.norm(res));rng=np.random.default_rng(11);pert=u+1e-7*rng.normal(size=u.shape);rp=bridge.evaluate(pert,pressure);other=own(torch.tensor(pert),pressure).detach().numpy();relative=float(np.linalg.norm(other-rp['residual'])/np.linalg.norm(rp['residual']));assert relative<1e-6 and absolute<1e-8,(relative,absolute)
