direction=rng.normal(size=u.shape);direction/=np.linalg.norm(direction);h=1e-8;plus=bridge.evaluate(pert+h*direction,pressure,False);minus=bridge.evaluate(pert-h*direction,pressure,False);fd=(float(plus['loss'])-float(minus['loss']))/(2*h);ad=float((rp['gradient']*direction).sum());error=abs(fd-ad)/max(abs(fd),abs(ad),1e-12);assert error<1e-4,(fd,ad,error)
# Pressure sign is checked through reference pressure work at the converged field.
rzero=bridge.evaluate(np.zeros_like(u),0,False)['residual'];rload=bridge.evaluate(np.zeros_like(u),pressure,False)['residual'];work=float(((rload-rzero)*u).sum());assert work<0,work
assert float(rp['loss'])>float(reference['loss'])
assert np.isfinite(a['displacements']).all()
J=np.concatenate([own.detF(torch.tensor(z)).detach().numpy() for z in a['displacements']])
out={'independent_numpy_torch_vs_trusted_residual_max_abs_N_at_reference':absolute,'independent_vs_trusted_relative_l2_at_perturbed_state':relative,'reference_independent_force_l2_N':norm,'trusted_normalized_residual_loss':float(reference['loss']),'perturbed_normalized_residual_loss':float(rp['loss']),'VJP_directional_finite_difference':fd,'VJP_autodiff':ad,'VJP_relative_error':error,'positive_pressure_work_at_solution_J':work,'minimum_endpoint_detF_all_cases':float(J.min()),'inverted_element_fraction':float((J<=0).mean()),'all_dofs_free':True,'natural_BC_terms':'follower pressure and epi/base Robin independently assembled; no Dirichlet reactions','gates':'independent finite-strain dynamic assembly, trusted solution, tangent VJP, pressure sign, Jacobians passed; earlier synthetic tests cover rigid/affine/unit quadrature','scope':'one fixed cardiac geometry, startup pressure variants; not a full cardiac cycle'}
