if (P/'experiments/metrics/physics_experiment.json').exists():
 from lv_surrogate.models.reduced_graph import ReducedGraphSurrogate
 exp=json.loads((P/'experiments/metrics/physics_experiment.json').read_text());selected=exp['lambda_selection']['selected'];state=torch.load(P/f'experiments/checkpoints/cardiac_startup_v1/{selected}.pt',map_location='cpu',weights_only=False);model=ReducedGraphSurrogate(*[state[k] for k in ['field_mean','basis','coefficient_scale','node_features','edge_features','topology']]).double();model.load_state_dict(state);pressure=float(a['pressures'][15]);pn=(pressure-exp['pressure_normalizer']['mean_Pa'])/exp['pressure_normalizer']['std_Pa'];prediction=model(torch.tensor([pn],dtype=torch.float64))[0];loss=bridge.loss(prediction,pressure);loss.backward();norm=float(sum(p.grad.square().sum() for p in model.parameters() if p.grad is not None).sqrt());assert norm>0 and np.isfinite(norm);out['physics_only_neural_parameter_gradient_norm']=norm;out['physics_loss_backpropagation']='verified through trained graph/POD model using physics loss only'
